 		/* register media device */
 		ret = media_device_register(dev->media_dev);
 		if (ret) {
 			dev_err(&udev->dev,
 				"Media Device Register Error: %d\n", ret);
 			return ret;
 		}
 	} else {
 		/*
 		 * Call au0828_media_graph_notify() to connect
